36	const COMPONENT_BLOCK_SIZE = 3;
37	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
38	
39	const isComponentBlock = (items: Item[]): boolean =>
40	  items.length === COMPONENT_BLOCK_SIZE &&
41	  items.every((item) => item.type === items[0].type);
42	
43	const basePremiumForItems = (items: Item[]): number => {
44	  if (isComponentBlock(items)) return COMPONENT_BLOCK_BASE_PREMIUM;
45	  return items.reduce(
46	    (total, item) => total + BASE_PREMIUM_BY_ITEM_TYPE[item.type],
47	    0,
48	  );
49	};
50	
51	const premiumForItems = (items: Item[]): number => {
52	  const basePremium = basePremiumForItems(items);
53	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
54	  return basePremium + firstInsuranceSurcharge;
55	};
56	
57	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
58	  results: scenario.steps.map((step) => ({
59	    premium: Math.ceil(premiumForItems(step.items) + PROCESSING_FEE),
60	  })),
61	});
