const premiumBeforeProcessingFee = (items: Item[]): number => {
  const basePremium = basePremiumForItems(items);
  return basePremium + basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
};

export const runScenario = (scenario: Scenario): ScenarioOutput => ({
  results: scenario.steps.map((step) => ({
    premium: Math.ceil(premiumBeforeProcessingFee(step.items) + PROCESSING_FEE),
  })),
});
